{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table Maplemonk.Hyuman_DRR_Sales_Consolidated_Intermediate as select data_source as source, date(order_date) as order_date, upper(coalesce(im.Component_Product_Code,cs.Child_SKU,s.commonsku)) AS SKU, upper(marketplace) as marketplace, case when upper(warehouse) like \'HYUMAN_BLR\' then \'SR Bangalore\' when upper(warehouse) like \'HYUMAN_KOL\' then \'SR Kolkata\' when upper(warehouse) like \'HYUMAN_MUM\' then \'SR Mumbai\' when upper(warehouse) like \'HYUMAN_GGN\' then \'SR Gurugram\' when upper(warehouse) like \'GUR_SAN_WH_NL_01NL\' then \'FBF Gurugram\' when upper(warehouse) like \'MALUR_BTS\' then \'FBF Bangalore\' when upper(warehouse) like \'ULUB_BTS\' then \'FBF Kolkata\' when upper(warehouse) like \'BHI_VAS_WH_NL_01NL\' then \'FBF Mumbai\' when upper(warehouse) like \'ESHOPBOX_GURGAON_FC3\' then \'Eshopbox Gurugram\' when upper(warehouse) like \'ESHOP_BANGALORESBLR\' then \'Eshopbox Bangalore\' when upper(warehouse) like \'ACCU\' then \'Eshopbox Kolkata\' when upper(warehouse) like \'ESHOP_XMUM2\' then \'Eshopbox Mumbai\' else upper(warehouse) end AS facility, sum(ifnull(quantity,0) * coalesce(im.component_quantity,cs.child_qty,1)) as units_sold from maplemonk.hyuman_sales_consolidated s left join (select upper(Product_Code) product_code, case when type = \'SIMPLE\' then upper(Product_Code) else upper(Component_Product_Code) end as component_product_code, ifnull(cast(nullif(component_quantity,\'\') as int64),1) as component_quantity from `MapleMonk.Hyuman_Unicommerce_get_item_master` qualify row_number() over (partition by upper(Product_Code),upper(Component_Product_Code) order by 1)=1 ) im on upper(im.product_code) = upper(s.commonsku) and s.data_source in (\'ESHOPBOX\') left join (SELECT upper(trim(SKU_s)) as sku, items.child_sku AS Child_SKU, cast(items.child_qty as int64) AS Child_Qty FROM maplemonk.gs_SKU_MAPPING_PARENT_CHILD, UNNEST([ STRUCT(Child_SKU_1 AS child_sku, SKU_1_QTY AS child_qty), STRUCT(Child_SKU_2 AS child_sku, SKU_2_QTY AS child_qty), STRUCT(Child_SKU_3 AS child_sku, SKU_3_QTY AS child_qty), STRUCT(Child_SKU_4 AS child_sku, SKU_4_QTY AS child_qty) ]) AS items WHERE items.child_sku IS NOT NULL AND items.child_sku <> \'-\' and upper(trim(SKU_s)) not in (select distinct upper(product_code) from MapleMonk.Hyuman_Unicommerce_get_item_master) ) cs on upper(trim(cs.SKU)) = upper(s.commonsku) and s.data_source in (\'ESHOPBOX\') where order_date is not null and (upper(order_status) not in (\'RETURNED\',\'CANCELLED\',\'RETURN REQUESTED\',\'UNDELIVERED\') or order_status is null) and (upper(oms_order_status) not in (\'CANCELLED\',\'RETURN ON THE WAY\',\'RETURN IN PROCESSING\',\'RETURN DELIVERED\',\'QUARANTINED\') or oms_order_status is null) and (upper(shipping_status) not in (\'CANCELLED\',\'RETURN_EXPECTED\',\'RETURNED\',\'RETURN_ACKNOWLEDGED\',\'REFUNDED\') or shipping_status is null) and s.data_source <> \'UNIWARE B2B\' and im.component_product_code is null and commonsku is null group by 1,2,3,4,5 ; create or replace table maplemonk.Hyuman_Drr_Factitems as WITH daily_sales AS ( SELECT source, facility, sku, order_date, SUM(units_sold) AS daily_qty FROM Maplemonk.Hyuman_DRR_Sales_Consolidated_Intermediate WHERE order_date < CURRENT_DATE() GROUP BY 1,2,3,4 ), thresholds AS ( SELECT source, facility, sku, ROUND( SAFE_DIVIDE(SUM(daily_qty),COUNT(DISTINCT order_date)) / 2,2) AS threshold_avg FROM daily_sales WHERE order_date BETWEEN DATE_SUB(CURRENT_DATE(), INTERVAL 28 DAY) AND DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY) GROUP BY 1,2,3 ) SELECT d.source, d.facility, d.sku, t.threshold_avg AS average, ROUND( SAFE_DIVIDE(SUM( CASE WHEN d.order_date BETWEEN DATE_SUB(CURRENT_DATE(), INTERVAL 7 DAY) AND DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY) THEN d.daily_qty END), COUNT( CASE WHEN d.order_date BETWEEN DATE_SUB(CURRENT_DATE(), INTERVAL 7 DAY) AND DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY) AND d.daily_qty >= t.threshold_avg THEN 1 END)),2) AS drr_7, ROUND( SAFE_DIVIDE(SUM( CASE WHEN d.order_date BETWEEN DATE_SUB(CURRENT_DATE(), INTERVAL 14 DAY) AND DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY) THEN d.daily_qty END), COUNT( CASE WHEN d.order_date BETWEEN DATE_SUB(CURRENT_DATE(), INTERVAL 14 DAY) AND DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY) AND d.daily_qty >= t.threshold_avg THEN 1 END)),2) AS drr_14, ROUND( SAFE_DIVIDE(SUM( CASE WHEN d.order_date BETWEEN DATE_SUB(CURRENT_DATE(), INTERVAL 28 DAY) AND DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY) THEN d.daily_qty END), COUNT( CASE WHEN d.order_date BETWEEN DATE_SUB(CURRENT_DATE(), INTERVAL 28 DAY) AND DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY) AND d.daily_qty >= t.threshold_avg THEN 1 END)),2) AS drr_28 FROM daily_sales d JOIN thresholds t ON d.source = t.source AND d.facility = t.facility AND d.sku = t.sku GROUP BY 1,2,3,4 ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            